void* AllocatePagedPoolWithTag(size_t size) {
    // Check for non-zero size to prevent invalid allocations
    if (size == 0) {
        return NULL;
    }

    // Calculate the total size needed for the allocation (header + data)
    // Assume a 4-byte header for storing the size
    size_t headerSize = sizeof(size_t);
    size_t totalSize = size + headerSize;

    // Allocate memory from the NonPagedPool using ExAllocatePoolWithTag
    void* allocatedBlock = ExAllocatePoolWithTag(NonPagedPool, totalSize, 'Pool');

    if (allocatedBlock == NULL) {
        return NULL; // Allocation failed
    }

    // Store the size in the header
    size_t* header = (size_t*)allocatedBlock;
    *header = size;

    // Return a pointer to the data portion of the block (after the header)
    return (void*)(allocatedBlock + headerSize);
}

void* allocate_non_paged_pool(size_t size) {
    size_t total_size;
    void* allocation;
    size_t* header;

    if (size == 0) {
        return NULL;
    }

    total_size = sizeof(size_t) + size;
    if (total_size < sizeof(size_t)) {
        return NULL;
    }

    allocation = ExAllocatePoolWithTag(NonPagedPool, total_size, 'POOL');
    if (allocation == NULL) {
        return NULL;
    }

    header = (size_t*)allocation;
    *header = size;
    return (void*)(header + 1);
}

