void* allocate_pooled_memory(size_t size) {
    if (size == 0) {
        return NULL;
    }

    // Reserve space for the header before the user data
    size_t total_size = sizeof(size_t) + size;
    if (total_size < size) {
        // Overflow occurred
        return NULL;
    }

    void* pool_memory = ExAllocatePoolWithTag(NonPagedPool, total_size, 'MEM1');
    if (pool_memory == NULL) {
        return NULL;
    }

    // Store the size in the header
    size_t* header = (size_t*)pool_memory;
    *header = size;
    void* data = (void*)(header + 1);

    return data;
}

void* allocate_memory_with_header(size_t size) {
    if (size == 0) {
        return NULL;
    }

    // Calculate total size including the header
    size_t total_size = sizeof(size_t) + size;

    // Allocate memory from NonPagedPool
    void* raw_memory = ExAllocatePoolWithTag(NonPagedPool, total_size, 'HDRM');

    if (raw_memory == NULL) {
        return NULL;
    }

    // Store the size in the header
    size_t* header = (size_t*)raw_memory;
    *header = size;

    // Return a pointer to the data portion (after the header)
    return (void*)(header + 1);
}
